  reasoning.application_facts=makeReason('moderate','Only explicit captured producer facts are populated. All application members exist; null facts retain missing detail, unsupported vocabulary or source applicability rather than an inferred protocol.',collectIds(a),['Standard examples are orientation and do not fill abbreviated producer observations.']);
