  const assessment={boundary_status:c.boundary,technology_family:c.family,claim_trust_level:tier,trust_basis:basis,classification_confidence:c.confidence,limiting_factors:c.limits,policy_reference:policy,reasoning};
  let technology_reference={status:c.boundary==='out_of_scope'?'not_assessed':'no_existing_match',research_key:null,product_id:null,formula_sha256:null,source_version:null,shared_markers:[],source_ids:[],limitation:'No closed-family reference is assigned to excluded or unrecognized-category research. Generic ingredient overlap is insufficient.'};
  if(c.reference){const ref=packet.policy_packet.owner_registry.find(r=>r.research_key===c.reference);const rp=packet.records.find(r=>r.slot_id===c.reference);const marker={sulfur_targeting_dimaleate:['Bis-Aminopropyl Diglycol Dimaleate'],designed_peptide:['sh-Oligopeptide-78'],maleate_ester:['Diethylhexyl Maleate'],acid_calcium_management:['Citric Acid'],gluconamide_gluconate:['Hydroxypropylgluconamide','Hydroxypropylammonium Gluconate']}[c.family];technology_reference={status:'matched',research_key:ref.research_key,product_id:null,formula_sha256:ref.normalized_sha256,source_version:ref.source_version,shared_markers:marker,source_ids:rp.formula_source_ids,limitation:'Exact frozen explanatory reference only. formula_sha256 is its ordered-normalized formula digest (serialization clarification), not raw_sha256. Shared chemistry does not transfer tier, efficacy, supplier, dose, protocol, fit or catalogue identity.'};}
  const applicability=[];
