  const fit=Object.fromEntries(['fine','normal','coarse'].map(d=>[d,unknown(`${id}: no captured ${d}-diameter suitability value; manufacturer all-hair/damage language, curl pattern or ingredient texture cannot supply a diameter fit flag.`)]));
