  const candidate_to_final_trace=[`Stage A candidates: ${original.candidate_families.length?original.candidate_families.join(', '):'none'}.`,c.why,`Final boundary: ${c.boundary}; family: ${c.family??'null'}; tier/basis: ${tier??'null'}/${basis??'null'}.`];
  const conflicts=[...(p.formula_conflicts??[]).map(x=>`${x.source_ids.join(', ')}: ${x.reason} Resolved=${x.resolved}; raw formula remains in the frozen named packet.`),...(p.conflicts??[])];
